      const _cdTarget = new Date(event.start_date).getTime();
      const _cdEls = ["edCdDays", "edCdHours", "edCdMins", "edCdSecs"].map((id) => document.getElementById(id));
      const _cdCard = document.getElementById("edCountdownCard");
      _tickCd();
